/**
 * For files being locally edited, get and return its mtime timestamp from workspace-state cache if present there,
 * else get from server. May update cache.
 * - If mtime fetched from server is later than local file mtime, or if `force` parameter is `true`, cache server mtime and return it.
 * - Otherwise if server fetch fails, clear cache entry and return -1.
 * - Otherwise cache local file mtime and return it.
 *
 * For other file types (e.g. isfs) return -1 and do not alter cache.
 * @param file File to check.
 * @param force If passed true, use server mtime.
 * @return mtime timestamp or -1.
 */
export async function checkChangedOnServer(file: CurrentTextFile | CurrentBinaryFile, force = false): Promise<number> {
  if (!file || !file.uri || schemas.includes(file.uri.scheme)) {
    return -1;
  }
  const api = new AtelierAPI(file.uri);
  const mtime =
    workspaceState.get(`${file.uniqueId}:mtime`, null) ||
    (await api
      .getDoc(file.name, file.uri)
      .then((data) => data.result)
      .then(async ({ ts, content }) => {
        const serverTime = Number(new Date(ts + "Z"));
        let sameContent: boolean;
        if (typeof file.content === "string") {
          const fileContent = file.content.split(/\r?\n/);
          sameContent = force
            ? false
            : (content as string[]).every((line, index) => line.trim() == (fileContent[index] || "").trim());
        } else {
          sameContent = force ? false : Buffer.compare(content as Buffer, file.content) === 0;
        }
        const mtime =
          force || sameContent ? serverTime : Math.max((await vscode.workspace.fs.stat(file.uri)).mtime, serverTime);
        return mtime;
      })
      .catch(() => -1));
  workspaceState.update(`${file.uniqueId}:mtime`, mtime > 0 ? mtime : undefined);
  return mtime;
}

// Synchronize the client version and the server version of the same file
export async function importFile(
  file: CurrentTextFile | CurrentBinaryFile,
  willCompile: boolean,
  ignoreConflict?: boolean,
  skipDeplCheck = false
): Promise<any> {
  if (!file) return;
  const api = new AtelierAPI(file.uri);
  if (!api.active) return Promise.reject();
  if (file.name.split(".").pop()!.toLowerCase() === "cls" && !skipDeplCheck) {
    if (await isClassDeployed(file.name, api)) {
      vscode.window.showErrorMessage(`Cannot import ${file.name} because it is deployed on the server.`, "Dismiss");
      return Promise.reject();
    }
  }
  let enc: boolean;
  let content: string[];
  if (typeof file.content === "string") {
    enc = false;
    content = file.content.split(/\r?\n/);

    // Avoid appending a blank line on every save, which would cause a web app file to grow each time
    if (file.name.includes("/") && content.length > 1 && content[content.length - 1] == "") {
      content.pop();
    }
  } else {
    enc = true;
    content = base64EncodeContent(file.content);
  }
  const mtime = await checkChangedOnServer(file);
  ignoreConflict =
    ignoreConflict ||
    mtime < 0 ||
    (notIsfs(file.uri) &&
      vscode.workspace.getConfiguration("objectscript", file.uri).get<boolean>("overwriteServerChanges"));
  try {
    const data = await api.putDoc(
      file.name,
      {
        content,
        enc,
        mtime,
      },
      ignoreConflict
    );
    // Update cache entry
    workspaceState.update(`${file.uniqueId}:mtime`, Number(new Date(data.result.ts + "Z")));

    if (!willCompile && isClass(file.name) && data.result.content.length) {
      // In this case, the file must be a CLS and data.result.content must be the new Storage definitions
      // (with the rest of the class if flags === 0)
      const oldContent = new TextDecoder().decode(await vscode.workspace.fs.readFile(file.uri));
      const oldContentArray = oldContent.split(/\r?\n/);
      const storage = Buffer.isBuffer(data.result.content)
        ? new TextDecoder().decode(data.result.content).split(/\r?\n/)
        : data.result.content;
      const newContentArray = updateStorage(oldContentArray, storage);
      if (oldContentArray.some((oldLine, index) => oldLine !== newContentArray[index])) {
        const EOL = ((<CurrentTextFile>file)?.eol ?? vscode.EndOfLine.LF) == vscode.EndOfLine.CRLF ? "\r\n" : "\n";
        const newContent = newContentArray.join(EOL);
        await vscode.workspace.fs.writeFile(file.uri, new TextEncoder().encode(newContent));
      }
    }
    // In case another extension has used an 'objectscript://' uri to load a document read-only from the server,
    // make it reload with what we just imported to the server.
    const serverUri = DocumentContentProvider.getUri(
      file.name,
      file.workspaceFolder,
      undefined,
      false,
      undefined,
      true
    );
    if (serverUri) documentContentProvider.update(serverUri);
  } catch (error) {
    if (error?.statusCode == 409) {
      const choices: string[] = [];
      if (!enc) {
        choices.push("Compare");
      }
      choices.push("Overwrite on Server", "Pull Server Changes", "Cancel");
      const action = await vscode.window.showErrorMessage(
        `Failed to import '${file.name}': The version of the file on the server is newer.
What do you want to do?`,
        ...choices
      );
      switch (action) {
        case "Compare":
          return vscode.commands
            .executeCommand(
              "vscode.diff",
              vscode.Uri.file(file.name).with({
                scheme: OBJECTSCRIPT_FILE_SCHEMA,
                authority: file.workspaceFolder,
                query: file.name.includes("/") ? "csp" : "",
              }),
              file.uri,
              `Server • ${file.name} ↔ Local • ${file.fileName}`
            )
            .then(() => Promise.reject());
        case "Overwrite on Server":
          // Clear cache entry
          workspaceState.update(`${file.uniqueId}:mtime`, undefined);
          // Overwrite
          return importFile(file, willCompile, true, true);
        case "Pull Server Changes":
          loadChanges([file], true);
          return Promise.reject();
        case "Cancel":
          return Promise.reject();
      }
      return Promise.reject();
    } else {
      handleError(error, `Failed to save file '${file.name}' on the server.`);
      return Promise.reject();
    }
  }
}

function updateOthers(others: string[], baseUri: vscode.Uri) {
  let workspaceFolder = vscode.workspace.getWorkspaceFolder(baseUri);
  if (!workspaceFolder && filesystemSchemas.includes(baseUri.scheme)) {
    // hack to deal with problem seen with isfs* schemes
    workspaceFolder = vscode.workspace.getWorkspaceFolder(baseUri.with({ path: "" }));
  }
  others.forEach((item) => {
    const uri = DocumentContentProvider.getUri(item, undefined, undefined, undefined, workspaceFolder?.uri);
    if (filesystemSchemas.includes(uri!.scheme)) {
      fileSystemProvider.fireFileChanged(uri!);
    } else if (uri!.scheme == OBJECTSCRIPT_FILE_SCHEMA) {
      documentContentProvider.update(uri!);
    }
  });
}

/**
 * Pull changes due to save/compile from server and write them into the local file.
 * Also used to refresh the local copy from the server outside of the save/compile workflow.
 * Pass `forceRefreshClasses` to replace the entire text of classes regardless of the
 * value of the `objectscript.refreshClassesOnSync` setting.
 */
export async function loadChanges(
  files: (CurrentTextFile | CurrentBinaryFile)[],
  forceRefreshClasses = false
): Promise<any> {
  if (!files.length) {
    return;
  }
  const api = new AtelierAPI(files[0].uri);
  // Use allSettled so we attempt to load changes for all files, even if some fail
  return api.actionIndex(files.map((f) => f.name)).then((data) =>
    Promise.allSettled(
      data.result.content.map(async (doc) => {
        if (doc.status.length) return;
        const file = files.find((f) => f.name == doc.name)!;
        const mtime = Number(new Date(doc.ts + "Z"));
        workspaceState.update(`${file.uniqueId}:mtime`, mtime > 0 ? mtime : undefined);
        if (notIsfs(file.uri)) {
          let content: Document["content"];
          if (
            !(
              isClass(file.uri.path) &&
              !vscode.workspace.getConfiguration("objectscript", file.uri).get("refreshClassesOnSync") &&
              !forceRefreshClasses
            )
          ) {
            content = (await api.getDoc(file.name, file.uri)).result.content;
          } else {
            // Insert/update the storage part of class definition.
            content = new TextDecoder().decode(await vscode.workspace.fs.readFile(file.uri)).split(/\r?\n/);
            let storage = (await api.getDoc(file.name, file.uri, undefined, true)).result.content;
            storage = Buffer.isBuffer(storage) ? new TextDecoder().decode(storage).split(/\r?\n/) : storage;
            content = updateStorage(content, storage);
          }
          exportedUris.add(file.uri.toString()); // Set optimistically
          await vscode.workspace.fs
            .writeFile(
              file.uri,
              Buffer.isBuffer(content)
                ? content
                : new TextEncoder().encode(
                    content.join(
                      ((<CurrentTextFile>file)?.eol ?? vscode.EndOfLine.LF) == vscode.EndOfLine.CRLF ? "\r\n" : "\n"
                    )
                  )
            )
            .then(undefined, (e) => {
              // Save failed, so remove this URI from the set
              exportedUris.delete(file.uri.toString());
              // Re-throw the error
              throw e;
            });
          if (isClassOrRtn(file.uri.path)) {
            // Update the document index
            updateIndex(file.uri, content);
          }
        } else if (filesystemSchemas.includes(file.uri.scheme)) {
          fileSystemProvider.fireFileChanged(file.uri);
        }
        updateOthers(doc.others, file.uri);
      })
    )
  );
}

function updateStorage(content: string[], storage: string[]): string[] {
  const storageMap = storageToMap(storage);
  let contentString = content.join("\n");
  contentString = contentString
    // update existing Storages
    .replaceAll(/\n(\s*storage\s+(\w+)\s*{\s*)(.*?)(>\s*})/gis, (_match, beforeXML, name, _oldXML, afterXML) => {
      let newXML = storageMap.get(name);
      if (newXML === undefined) {
        return "";
      }
      newXML = newXML.slice(0, newXML.length - 1);
      storageMap.delete(name);
      return "\n" + beforeXML + newXML + afterXML;
    });
  contentString = contentString
    // insert remaining Storages
    .replace(/}\s*$/, (m) => {
      for (const [name, content] of storageMap.entries()) {
        m = `Storage ${name}\n{\n${content}\n}\n\n${m}`;
      }
      return m;
    });
  return contentString.split("\n");
}

function storageToMap(storage: string[]): Map<string, string> {
  const map: Map<string, string> = new Map();
  let k: string | undefined;
  let v: string[] = [];
  for (const line of storage) {
    if (line.startsWith("Storage ")) {
      k = line.slice("Storage ".length, line.length);
      v = [];
    } else if (k !== undefined) {
      if (line === "{") {
        continue;
      } else if (line === "}") {
        map.set(k, v.join("\n"));
        k = undefined;
      } else {
        v.push(line);
      }
    }
  }
  return map;
}

export async function compile(docs: (CurrentTextFile | CurrentBinaryFile)[], askFlags = false): Promise<any> {
  docs = docs.filter(notNull);
  if (!docs.length) return;
  const wsFolder = vscode.workspace.getWorkspaceFolder(docs[0].uri);
  const defaultFlags = vscode.workspace
    .getConfiguration("objectscript", wsFolder || docs[0].uri)
    .get<string>("compileFlags");
  const flags = askFlags
    ? await vscode.window.showInputBox({ title: "Enter compilation flags and qualifiers", value: defaultFlags })
    : defaultFlags;
  if (flags == undefined) return; // User clicked out of input box
  const api = new AtelierAPI(docs[0].uri);
  const docNames = docs.map((d) => d.name);
  // Determine the line ending to use for other documents affected
  // by compilation so we don't need to read their contents
  const eol = (<CurrentTextFile>docs.find((d) => (<CurrentTextFile>d)?.eol))?.eol ?? vscode.EndOfLine.LF;
  return vscode.window
    .withProgress(
      {
        cancellable: true,
        location: vscode.ProgressLocation.Notification,
        title: `Compiling: ${docs.length == 1 ? docs[0].name : docs.length + " files"}`,
      },
      (progress, token: vscode.CancellationToken) =>
        api
          .asyncCompile(docNames, token, flags)
          .then((data) => {
            const info = docs.length > 1 ? "" : `${docs[0].name}: `;
            if (data.status && data.status.errors && data.status.errors.length) {
              throw new Error(`${info}Compile error`);
            }
            if (wsFolder) {
              // Make sure that we update the content for any
              // other documents affected by this compilation
              data.result.content.forEach((f) => {
                if (docNames.includes(f.name)) return;
                getUrisForDocument(f.name, wsFolder).forEach((u) => {
                  docs.push({
                    name: f.name,
                    uri: u,
                    uniqueId: `${wsFolder.name}:${f.name}`,
                    eol,
                    // These three keys aren't used by loadChanges()
                    workspaceFolder: wsFolder.name,
                    fileName: u.fsPath,
                    content: "",
                  });
                });
              });
            }
            return docs;
          })
          .catch((error) => {
            compileErrorMsg(error);
            // Always fetch server changes, even when compile failed or got cancelled
            return docs;
          })
    )
    .then(loadChanges);
}

export async function importAndCompile(document?: vscode.TextDocument, askFlags = false): Promise<any> {
  const file = currentFile(document);
  if (!file || filesystemSchemas.includes(file.uri.scheme) || !new AtelierAPI(file.uri).active) {
    // Not for server-side URIs or folders with inactive server connections
    return;
  }

  try {
    if (isCompilable(file.name)) {
      await importFile(file, true);
      compile([file], askFlags);
    } else {
      await importFile(file, false);
    }
  } catch {
    // importFile handles any server errors
  }
}

export async function compileOnly(document?: vscode.TextDocument | null, askFlags = false): Promise<any> {
  document =
    document ||
    (vscode.window.activeTextEditor && vscode.window.activeTextEditor.document
      ? vscode.window.activeTextEditor.document
      : null);
  if (!document) return;
  const file = currentFile(document);
  if (!file || !new AtelierAPI(file.uri).active) return;

  if (document.isDirty) {
    // Don't compile if document is dirty
    vscode.window.showWarningMessage(`Cannot compile '${file.name}' because it has unpersisted changes.`, "Dismiss");
    return;
  }

  if (isCompilable(file.name)) compile([file], askFlags);
}

// Compiles all files types in the namespace
export async function namespaceCompile(): Promise<any> {
  const api = new AtelierAPI();
  const fileTypes = ["*.CLS", "*.MAC", "*.INC", "*.BAS"];
  if (!api.active) return;
  const confirm = await vscode.window.showWarningMessage(
    `Compiling all files in namespace ${api.ns} might be expensive. Are you sure you want to proceed?`,
    "Cancel",
    "Confirm"
  );
  if (confirm !== "Confirm") {
    // Don't compile without confirmation
    return;
  }
  vscode.window.withProgress(
    {
      cancellable: true,
      location: vscode.ProgressLocation.Notification,
      title: `Compiling namespace ${api.ns}`,
    },
    (progress, token: vscode.CancellationToken) =>
      api
        .asyncCompile(fileTypes, token, vscode.workspace.getConfiguration("objectscript").get<string>("compileFlags"))
        .then((data) => {
          if (data.status && data.status.errors && data.status.errors.length) {
            throw new Error(`Compiling Namespace: ${api.ns} Error`);
          }
        })
        .catch(() => {
          vscode.window.showErrorMessage(
            `Compiling namespace '${api.ns}' failed. Check the 'ObjectScript' Output channel for details.`,
            "Dismiss"
          );
        })
        .then(() => {
          // Always fetch server changes, even when compile failed or got cancelled
          const file = currentFile();
          return loadChanges([file!]);
        })
  );
}

async function importFiles(files: vscode.Uri[], noCompile = false) {
  if (!files.length) return;
  const textDecoder = new TextDecoder();
  const toCompile: (CurrentTextFile | CurrentBinaryFile)[] = [];
  const rateLimiter = new RateLimiter(50);
  await Promise.allSettled<void>(
    files.map((uri) =>
      rateLimiter.call(async () => {
        const contentBytes = await vscode.workspace.fs.readFile(uri);
        const curFile = currentFileFromContent(
          uri,
          isText(uri.path.split("/").pop(), Buffer.from(contentBytes))
            ? textDecoder.decode(contentBytes)
            : Buffer.from(contentBytes)
        );
        if (curFile) {
          if (typeof curFile.content == "string" && isCompilable(curFile.name)) {
            toCompile.push(curFile);
          }
          await importFile(curFile, !noCompile);
          outputChannel.appendLine("Imported file: " + curFile.fileName);
        }
      })
    )
  );

  if (!noCompile && toCompile.length > 0) {
    await compile(toCompile);
  }
}

export async function importFolder(uri: vscode.Uri, noCompile = false): Promise<any> {
  if (!(uri instanceof vscode.Uri)) return;
  if (filesystemSchemas.includes(uri.scheme)) return; // Not for server-side URIs
  if ((await vscode.workspace.fs.stat(uri)).type != vscode.FileType.Directory) {
    return importFiles([uri], noCompile);
  }
  importFiles(urisInFolder(uri), noCompile);
}

export async function compileExplorerItems(nodes: NodeBase[]): Promise<any> {
  const { wsFolder, namespace } = nodes[0];
  const conf = vscode.workspace.getConfiguration("objectscript", wsFolder);
  const api = new AtelierAPI(wsFolder.uri);
  if (namespace) api.setNamespace(namespace);
  const docs: string[] = [];
  for (const node of nodes) {
    if (node instanceof PackageNode) {
      switch (node.category) {
        case "RTN":
          docs.push(node.fullName + ".*.mac");
          break;
        case "CLS":
          docs.push(node.fullName + ".*.cls");
          break;
      }
    } else if (node instanceof RootNode && node.contextValue === "dataNode:cspApplication") {
      docs.push(node.fullName + "/*");
    } else {
      docs.push(node.fullName);
    }
  }
  return vscode.window.withProgress(
    {
      cancellable: true,
      location: vscode.ProgressLocation.Notification,
      title: `Compiling ${nodes.length === 1 ? nodes[0].fullName : nodes.length + " nodes"}`,
    },
    (progress, token: vscode.CancellationToken) =>
      api
        .asyncCompile(docs, token, conf.get<string>("compileFlags"))
        .then((data) => {
          const info = nodes.length > 1 ? "" : `${nodes[0].fullName}: `;
          if (data.status && data.status.errors && data.status.errors.length) {
            throw new Error(`${info}Compile error`);
          }
        })
        .catch((error) => compileErrorMsg(error))
  );
}

/** Prompt the user to compile documents after importing them */
async function promptForCompile(imported: string[], api: AtelierAPI, isIsfs: boolean): Promise<void> {
  // This cast is safe because the only two callers intialize api with a workspace folder URI
  const conf = vscode.workspace.getConfiguration("objectscript", <vscode.Uri>api.wsOrFile);
  // Prompt the user for compilation
  if (imported.length) {
    return vscode.window
      .showInformationMessage(
        `Imported ${imported.length == 1 ? imported[0] : `${imported.length} files`}. Compile ${
          imported.length > 1 ? "them" : "it"
        }?`,
        "Yes",
        "No"
      )
      .then((response) => {
        if (response == "Yes") {
          // Compile the imported files
          return vscode.window.withProgress(
            {
              cancellable: true,
              location: vscode.ProgressLocation.Notification,
              title: `Compiling: ${imported.length == 1 ? imported[0] : imported.length + " files"}`,
            },
            (progress, token: vscode.CancellationToken) =>
              api
                .asyncCompile(imported, token, conf.get<string>("compileFlags"))
                .then((data) => {
                  const info = imported.length > 1 ? "" : `${imported[0]}: `;
                  if (data.status && data.status.errors && data.status.errors.length) {
                    throw new Error(`${info}Compile error`);
                  }
                })
                .catch((error) => compileErrorMsg(error))
                .finally(() => {
                  if (isIsfs) {
                    // Refresh the files explorer to show the new files
                    vscode.commands.executeCommand("workbench.files.action.refreshFilesExplorer");
                  }
                })
          );
        } else {
          if (isIsfs) {
            // Refresh the files explorer to show the new files
            vscode.commands.executeCommand("workbench.files.action.refreshFilesExplorer");
          }
          return Promise.resolve();
        }
      });
  } else {
    return Promise.resolve();
  }
}

interface FileQuickPickItem extends vscode.QuickPickItem {
  file: string;
}

export async function importArbitraryFiles(): Promise<any> {
  try {
    const wsFolderUri = await getWsServerConnection("2023.2.0");
    if (!wsFolderUri) {
      if (wsFolderUri === undefined) {
        // Strict equality needed because undefined == null
        vscode.window.showErrorMessage(
          "'Import Files...' command requires an active server connection to InterSystems IRIS version 2023.2 or above.",
          "Dismiss"
        );
      }
      return;
    }
    const api = new AtelierAPI(wsFolderUri);
    let defaultUri = wsFolderUri;
    if (defaultUri.scheme == FILESYSTEM_SCHEMA) {
      // Need a default URI without the isfs scheme or the open dialog
      // will show the server-side files instead of local ones
      defaultUri = lastUsedLocalUri() ?? vscode.workspace.workspaceFile;
      if (defaultUri.scheme != "file") {
        vscode.window.showErrorMessage("'Import Files...' command is not supported for unsaved workspaces.", "Dismiss");
        return;
      }
      // Remove the file name from the URI
      defaultUri = defaultUri.with({ path: defaultUri.path.split("/").slice(0, -1).join("/") });
    }
    // Prompt the user the file to import
    const supportedExts = ["cls", "mac", "int", "inc", "xml", "rtn", "ro"];
    let uris = await vscode.window.showOpenDialog({
      canSelectFiles: true,
      canSelectFolders: false,
      canSelectMany: true,
      openLabel: "Import",
      filters: {
        "InterSystems Files": supportedExts,
      },
      defaultUri,
    });
    if (!uris?.length) return;
    // Filter out non-importable files
    uris = uris.filter((uri) => supportedExts.includes(uri.path.split(".").pop()!.toLowerCase()));
    if (uris.length == 0) {
      vscode.window.showErrorMessage("No selected files are importable.", "Dismiss");
      return;
    }
    lastUsedLocalUri(uris[0]);
    // Read the files
    const fileTimestamps: Map<string, string> = new Map();
    const filesToList = await Promise.allSettled(
      uris.map(async (uri) => {
        fileTimestamps.set(
          uri.fsPath,
          new Date((await vscode.workspace.fs.stat(uri)).mtime).toISOString().replace("T", " ").split(".")[0]
        );
        return {
          file: uri.fsPath,
          content: new TextDecoder().decode(await vscode.workspace.fs.readFile(uri)).split(/\r?\n/),
        };
      })
    ).then((results) =>
      results
        .map((result) => {
          if (result.status == "fulfilled") {
            return result.value;
          } else {
            handleError(result.reason);
            return null;
          }
        })
        .filter(notNull)
        .map((f) => f!)
    );
    if (filesToList.length == 0) {
      vscode.window.showErrorMessage("Failed to read the text of every selected file.", "Dismiss");
      return;
    }
    // List the documents in the files
    const documentsPerFile = await api.actionXMLList(filesToList).then((data) => data.result.content);
    // Prompt the user to select documents to import
    const quickPickItems = documentsPerFile
      .filter((file) => {
        if (file.status != "") {
          outputChannel.appendLine(`Failed to list documents in file '${file.file}': ${file.status}`);
          return false;
        } else {
          return true;
        }
      })
      .flatMap((file) => {
        const items: FileQuickPickItem[] = [];
        if (file.documents.length > 0) {
          // Add a separator for this file
          items.push({
            label: file.file,
            kind: vscode.QuickPickItemKind.Separator,
            file: file.file,
          });
          file.documents.forEach((doc) =>
            items.push({
              label: doc.name,
              picked: true,
              detail: `${
                doc.ts.toString() != "-1" ? `Server timestamp: ${doc.ts.split(".")[0]}` : "Does not exist on server"
              }, ${fileTimestamps.has(file.file) ? `File timestamp: ${fileTimestamps.get(file.file)}` : ""}`,
              file: file.file,
            })
          );
        }
        return items;
      });
    // Prompt the user for documents to import
    let docsToImport = await vscode.window.showQuickPick(quickPickItems, {
      canPickMany: true,
      ignoreFocusOut: true,
      title: `Select the documents to import into namespace '${api.ns}' on server '${api.serverId}'`,
    });
    if (!docsToImport?.length) return;
    outputChannel.show(true);
    const isIsfs = filesystemSchemas.includes(wsFolderUri.scheme);
    if (isIsfs) {
      // The user is importing into a server-side folder
      const docNames = [...new Set(docsToImport.map((qpi) => qpi.label))].join(",");
      // Fire the import list User Action
      await new StudioActions().fireImportUserAction(api, docNames);
      // Check the status of the documents to be imported and skip any that are read-only
      await api.actionQuery("select * from %Atelier_v1_Utils.Extension_GetStatus(?)", [docNames]).then((data) => {
        const readOnly: string[] = [];
        data?.result?.content?.forEach((e) => {
          if (!e.editable) {
            readOnly.push(e.name);
            outputChannel.appendLine(
              `Skipping '${e.name}' because it has been marked read-only by server-side source control.`
            );
          }
        });
        if (readOnly.length) {
          docsToImport = docsToImport!.filter((qpi) => {
            const nameSplit = qpi.label.split(".");
            return !readOnly.includes(`${nameSplit.slice(0, -1).join(".")}.${nameSplit.pop()!.toUpperCase()}`);
          });
        }
      });
    }
    // Import the selected documents
    const filesToLoad: { file: string; content: string[]; selected: string[] }[] = filesToList.map((f) => {
      return { selected: [], ...f };
    });
    docsToImport.forEach((qpi) =>
      // This is safe because every document came from a file
      filesToLoad[filesToLoad.findIndex((f) => f.file == qpi.file)].selected.push(qpi.label)
    );
    const importedPerFile = await api
      .actionXMLLoad(filesToLoad.filter((f) => f.selected.length > 0))
      .then((data) => data.result.content);
    const imported = importedPerFile.flatMap((file) => {
      if (file.status != "") {
        outputChannel.appendLine(`Importing documents from file '${file.file}' produced error: ${file.status}`);
      }
      return file.imported;
    });
    // Prompt the user for compilation
    promptForCompile([...new Set(imported)], api, isIsfs);
  } catch (error) {
    handleError(error, "Error executing 'Import Files...' command.");
  }
}
